class Solution:
    def smallestSubsequence(self, s: str, k: int, letter: str, repetition: int) -> str:
        best = [None]

        def dfs(start, cur):
            if len(cur) == k:
                if cur.count(letter) >= repetition and (best[0] is None or cur < best[0]):
                    best[0] = cur
                return
            for i in range(start, len(s)):
                dfs(i + 1, cur + s[i])

        dfs(0, "")
        return best[0]

