class Solution {
public:
    void dfs(const string& s, int k, char letter, int repetition, int start,
             string& cur, string& best) {
        if ((int)cur.size() == k) {
            if (count(cur.begin(), cur.end(), letter) >= repetition &&
                (best.empty() || cur < best)) best = cur;
            return;
        }
        for (int i = start; i < (int)s.size(); i++) {
            cur.push_back(s[i]);
            dfs(s, k, letter, repetition, i + 1, cur, best);
            cur.pop_back();
        }
    }
    string smallestSubsequence(string s, int k, char letter, int repetition) {
        string cur, best;
        dfs(s, k, letter, repetition, 0, cur, best);
        return best;
    }
};

