class Solution {
    private String best = null;

    public String smallestSubsequence(String s, int k, char letter, int repetition) {
        dfs(s, k, letter, repetition, 0, new StringBuilder());
        return best;
    }

    private void dfs(String s, int k, char letter, int repetition, int start, StringBuilder cur) {
        if (cur.length() == k) {
            int cnt = 0;
            for (int i = 0; i < k; i++) if (cur.charAt(i) == letter) cnt++;
            if (cnt >= repetition && (best == null || cur.toString().compareTo(best) < 0)) {
                best = cur.toString();
            }
            return;
        }
        for (int i = start; i < s.length(); i++) {
            cur.append(s.charAt(i));
            dfs(s, k, letter, repetition, i + 1, cur);
            cur.deleteCharAt(cur.length() - 1);
        }
    }
}

