class Solution:
    def smallestSubsequence(self, s: str, k: int, letter: str, repetition: int) -> str:
        n = len(s)
        suffix = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suffix[i] = suffix[i + 1] + (s[i] == letter)
        stack = []
        cnt = 0
        for i, c in enumerate(s):
            while (stack and stack[-1] > c and len(stack) + n - i - 1 >= k
                   and cnt - (stack[-1] == letter) + suffix[i] >= repetition):
                cnt -= stack.pop() == letter
            if len(stack) < k and (c == letter or repetition - cnt <= k - len(stack) - 1):
                stack.append(c)
                cnt += c == letter
        return ''.join(stack)

