class Solution {
public:
    string smallestSubsequence(string s, int k, char letter, int repetition) {
        int n = s.size();
        vector<int> suffix(n + 1, 0);
        for (int i = n - 1; i >= 0; i--) suffix[i] = suffix[i + 1] + (s[i] == letter);
        string st;
        int cnt = 0;
        for (int i = 0; i < n; i++) {
            char c = s[i];
            while (!st.empty() && st.back() > c && (int)st.size() + n - i - 1 >= k
                   && cnt - (st.back() == letter) + suffix[i] >= repetition) {
                cnt -= st.back() == letter;
                st.pop_back();
            }
            if ((int)st.size() < k && (c == letter || repetition - cnt <= k - (int)st.size() - 1)) {
                st.push_back(c);
                cnt += c == letter;
            }
        }
        return st;
    }
};

