class Solution {
    public String smallestSubsequence(String s, int k, char letter, int repetition) {
        int n = s.length();
        int[] suffix = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) suffix[i] = suffix[i + 1] + (s.charAt(i) == letter ? 1 : 0);
        StringBuilder sb = new StringBuilder();
        int cnt = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            while (sb.length() > 0 && sb.charAt(sb.length() - 1) > c
                    && sb.length() + n - i - 1 >= k
                    && cnt - (sb.charAt(sb.length() - 1) == letter ? 1 : 0) + suffix[i] >= repetition) {
                if (sb.charAt(sb.length() - 1) == letter) cnt--;
                sb.deleteCharAt(sb.length() - 1);
            }
            if (sb.length() < k && (c == letter || repetition - cnt <= k - sb.length() - 1)) {
                sb.append(c);
                if (c == letter) cnt++;
            }
        }
        return sb.toString();
    }
}

