    const n = s.length;
    const suffix = new Array(n + 1).fill(0);
    for (let i = n - 1; i >= 0; i--) suffix[i] = suffix[i + 1] + (s[i] === letter ? 1 : 0);
    const stack = [];
    let cnt = 0;
    for (let i = 0; i < n; i++) {
        const c = s[i];
        while (stack.length && stack[stack.length - 1] > c &&
               stack.length + n - i - 1 >= k &&
               cnt - (stack[stack.length - 1] === letter ? 1 : 0) + suffix[i] >= repetition) {
            if (stack.pop() === letter) cnt--;
        }
        if (stack.length < k && (c === letter || repetition - cnt <= k - stack.length - 1)) {
            stack.push(c);
            if (c === letter) cnt++;
        }
    }
    return stack.join('');
};
